import json
from pathlib import Path
from fractions import Fraction

BASE=Path(__file__).resolve().parent
plan=json.loads((BASE/'case-plan.json').read_text(encoding='utf-8-sig'))
root=BASE/'company-video-grammar-analyzer-workspace/iteration-1'
defs={c['case_id']:c for c in plan['cases']}

def obs(case):
    c=defs[case]; log=json.loads(Path(c['input_log']).read_text(encoding='utf-8-sig'))
    evidence=[]
    for i,f in enumerate(log['frames']):
        evidence.append({'id':f['frame_id'],'path':f['path'],'actual_seconds':f['actual_playback_seconds'],
          'role':'context_after' if float(Fraction(f['actual_playback_seconds']))>=c['window_seconds'][1] else 'within',
          'inspected_via':str(Path(f['path']).parent/f'board-{i//12+1}.jpg'),
          'inspection_note':'보드 내 프레임 실제 열람; 원본 해상도 전체를 1:1로 판독한 것은 아님'})
    d={'schema_version':'a3-observation-0.1','case_id':case,'source':c['source'],'window_seconds':c['window_seconds'],
      'method':'view_image로 지정 구간 보드 3장 전부 및 대표 원본 PNG를 열람. 보드 순차 비교로 상태와 순서를 기록. 로그의 실제 PTS 사용. 연속 재생/전 프레임 검수/속도 계측은 하지 않음.',
      'document_mode':'sourceSHAverified_text_extract_with_locators; no_slide_layout_review',
      'audio_reviewed':False,'evidence':evidence,'objects':[],'document_comparison':[],
      'coverage':{'overview':'지정 구간만 검사. 전체 영상 검수 아님. 끝 시각 프레임은 context_after.',
         'secondary_details':'배경·제목·자막·아이콘·강조색을 함께 검사.',
         'internal_content':'별도 객체의 사건에 화면 속 UI 상태를 기록.', 'unresolved':[]},
      'hypotheses':[],
      'limitations':['선택 프레임 사이의 시작/종료·미세 동작은 확인하지 못함. 시간은 관측 상태 경계이며 정확한 키프레임 시각이 아님.',
        '오디오 미디코딩·미청취. 자막과 음성의 일치나 박자 동기화 판단 불가.',
        '픽셀 좌표 추적이나 속도 측정이 없어 가감속 곡선은 unknown. 보드/원본 표시 시 축소가 있어 작은 UI 값은 전수 판독하지 않음.',
        '문서는 기존 텍스트 추출본과 위치자를 대조. 원본 슬라이드 배치·문서 이미지·내장영상은 검수하지 않음.'],
      'files_read':[str(BASE/'case-plan.json'),str(BASE/'output-format.md'),c['input_log'],c['document'],c['document_record']]+sorted(set(e['inspected_via'] for e in evidence))}
    return d

def ev(d,desc,times,prop,order='',easing='unknown',status='observed',limits=None):
    ids=[]
    for t in times:
        f=next(e for e in d['evidence'] if float(Fraction(e['actual_seconds']))==t)
        ids.append(f['id'])
    return {'description':desc,'properties':prop,'time_seconds':[min(times),max(times)],'evidence_ids':ids,
      'direction_order':order,'easing':{'property':','.join(prop),'classification':easing,
        'basis':'표본 간 상태 비교. 연속 위치/불투명도 측정 없음.' if easing=='unknown' else '이 사건은 정적 배치/내용 유지 관찰.'},
      'status':status,'limitations':limits or []}

def obj(d,id,name,events,parent=None):d['objects'].append({'id':id,'name':name,'parent':parent,'events':events})
def native(d,t):
    f=next(e for e in d['evidence'] if float(Fraction(e['actual_seconds']))==t)
    f['native_png_also_inspected']=True;d['files_read'].append(f['path'])
def save(d,summary):
    out=root/f"eval-{d['case_id']}"/'without_skill/outputs';out.mkdir(parents=True,exist_ok=True)
    (out/'observations.json').write_text(json.dumps(d,ensure_ascii=False,indent=2),encoding='utf-8')
    (out/'observations.md').write_text(summary,encoding='utf-8')

